from pathlib import Path
import json,numpy as np,html
p=Path(__file__).resolve().parent;r=json.loads((p/'single-cycle-summary.json').read_text());runs=[]
for f in sorted(p.glob('*.npz')):
 if f.stem=='single-cycle':continue
 with np.load(f) as z:
  runs.append(dict(name=f.stem,frames=len(z['qpos']),finite=bool(np.isfinite(z['qpos']).all()),final_counter=int(z['userdata'][-1,2]),final_cube_height_m=float(z['trace'][-1,4]),final_contacts=z['trace'][-1,12:14].astype(int).tolist()))
summary=dict(user_objective='Несколько произвольных ходов 2×2 подряд без сброса, с отпусканием, отходом и возвратом рук в повторяемый хват после каждого хода.',objective_achieved=False,trial_count=len(runs),all_saved_qpos_finite=all(x['finite'] for x in runs),best_single_cycle=r,runs=runs,second_turn_original_model=dict(run='physical-horizontal',relative_layer_angle_after_hold_deg=89.20762788172172,corner_orientation_max_error_deg=5.579778493475141,cube_center_drift_m=.05954131913178349,next_regrip='grasp lost'),limits=['No composable move library, arbitrary R/F/U sequences, or reliable whole-cube reorientation primitives were obtained.','Only seed 0 deterministic replay is verified; no perturbation robustness claim.','Most initial sweeps used an experimental layer latch; the delivered macro-follow07 cycle uses the unmodified installed native mechanism.','The accepted flag in detent-return is a local search filter, not acceptance of the user objective.','No new APK was built or installed during this continuation.'])
(p/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))
rows=''.join(f"<tr><td>{html.escape(x['name'])}</td><td>{x['frames']/100:.2f}</td><td>{x['final_counter']}</td><td>{x['final_cube_height_m']:.3f}</td><td>{x['final_contacts']}</td></tr>" for x in runs)
doc='''<!doctype html><meta charset="utf-8"><title>Rubik 2×2 — отпускание и возврат</title><style>body{font:17px/1.6 system-ui;max-width:1100px;margin:36px auto;padding:0 24px;background:#112029;color:#e3eef3}h1,h2{line-height:1.25}a{color:#83d7ff}video{width:100%;border-radius:12px}table{border-collapse:collapse;font-size:14px;width:100%}td,th{padding:7px;border-bottom:1px solid #36505d;text-align:left}.status{border-left:5px solid #e7b366;background:#243540;padding:15px}code{color:#a5e8d2}</style>
<h1>Кубик 2×2: поворот → отпускание → отход → перехват</h1><p>15 октября 2026 · HOMIE Standing · исходная среда MuJoCo</p>
<p class="status"><b>Цель с несколькими произвольными ходами ещё не достигнута.</b> Найден один физический цикл с отпусканием и повторным захватом. Следующий ход или перехват теряет хват; этот результат нельзя использовать как готовый повторяемый примитив.</p>
<video controls preload="metadata" src="macro-follow07-cycle.mp4" poster="macro-follow07-release.png"></video>
<h2>Что подтверждено</h2><p>Один поворот F, выравнивание, раскрытие правой руки, отход и повторный захват. Правая рука без нагруженных контактов 1,2 с; максимальный измеренный зазор между её коллайдерами и кубиком — 8,68 см. Во всём цикле нет контактов кубика со столом, корпусом или предплечьями: удерживают только кисти.</p>
<p>После цикла центр кубика отличается на 2,42 мм, общая ориентация — на 5,12°. После учёта ожидаемого хода максимальная ошибка положения углового элемента — 0,71 мм, ориентации — 2,37°. Запястья возвращаются хуже: смещение слева/справа 28,1/16,2 мм, поворот 12,27/3,64°. Поэтому близкая поза самого кубика ещё не даёт повторяемого хвата.</p>
<p>В отдельном варианте с точным возвратом команд запястий их физическая ошибка составила 1,45/5,92 мм, однако кубик сместился на 26,3 мм и повернулся на 12,24°. Второй полный цикл этого варианта потерял захват.</p>
<h2>Проверка физики и воспроизведения</h2><p>Показанная траектория использует исходный установленный механизм кубика, ту же сцену, приводы и контакты. Нет переносов qpos, привязки кубика к рукам или внешних сил. Native snapshot используется только для поиска альтернатив; выбранные команды отдельно воспроизведены непрерывно с чистого старта: 3196 кадров, максимальная ошибка qpos и userdata — ровно 0, предупреждений MuJoCo — 0.</p>
<p>В ранних поисковых вариантах использовалась экспериментальная фиксация выбранного слоя и отдельные команды большого пальца; они не входят в показанный цикл. Видео — офлайн воспроизведение физики, не запись экрана Quest. Установка на шлем и живая проверка этой траектории не выполнялись.</p>
<h2>Файлы</h2><ul><li><a href="single-cycle.npz">Состояния, команды и контакты одного цикла</a></li><li><a href="single-cycle-wrist-commands.csv">Цели запястий и Grip, 100 Гц</a></li><li><a href="single-cycle-summary.json">Метрики и ограничения</a></li><li><a href="macro-follow07-replay.json">Точный непрерывный replay</a></li><li><a href="original-native-provenance.json">Сравнение native исходников с установленной версией</a></li><li><a href="macro_follow.py">Контроллер показанного эксперимента</a></li><li><a href="physical_check.py">Проверка хода по восьми угловым элементам</a></li></ul>
<p>Показанный запуск: <code>FOLLOW_GAIN=.7 CYCLES=5 RUBIK_RUN=macro-follow07 .venv/bin/python outputs/rubik-canonical-20261015/macro_follow.py</code>. Видеофрагмент заканчивается до неудачного следующего хода; полный исходный прогон и его неудача сохранены в <a href="macro-follow07.npz">macro-follow07.npz</a>.</p>
<h2>Поисковые прогоны</h2><p>TRIAL_COUNT сохранённых вариантов, все qpos конечны. Счётчик ходов в таблице не является успехом: он срабатывает до полной посадки слоя и может увеличиться при потере кубика.</p><table><tr><th>Вариант</th><th>Симуляция, с</th><th>Счётчик</th><th>Конечная высота, м</th><th>Маски кистей</th></tr>ROWS</table>'''
(p/'REPORT.html').write_text(doc.replace('TRIAL_COUNT',str(len(runs))).replace('ROWS',rows));print(json.dumps(dict(trials=len(runs),all_finite=summary['all_saved_qpos_finite'],objective_achieved=False)))
